scan_table_check.script:
(function (engine) {

	if (x_snc_codesanity.IsCheckApplicableToRecord())
	{
		var GetStringValue = x_snc_devtools.GetStringValue;
		var StringCheckRegEx = x_snc_devtools.StringCheckRegEx;

		if (GetStringValue(current.client_callable) != 'true')
		{
			return;
		}

		var strScript = GetStringValue(current.script);
		strScript = x_snc_devtools.ScriptRemoveComments(strScript);
		strScript = x_snc_devtools.ScriptEmptyStringLiterals(strScript);

		if (strScript.indexOf('AbstractAjaxProcessor') == -1)
		{
			return;
		}

		var strRegex = ',\\s*this\\s*\\)';

		var nPos = 0;
		while (true)
		{
			var nGetParamPos = strScript.indexOf('GetParam(', nPos);
			if (nGetParamPos == -1)
			{
				break;
			}
			var nClosePos = strScript.indexOf(')', nGetParamPos + 9);
			if (nClosePos == -1)
			{
				break;
			}
			var strCall = strScript.substring(nGetParamPos, nClosePos + 1);
			if (StringCheckRegEx(strCall, strRegex, '') != true)
			{
				engine.finding.increment();
			}
			nPos = nClosePos + 1;
		}
	}

})(engine);
